function cards(items){return `<div class="activity-grid">${items.map(a=>`<article class="activity-card" data-subject="${a.subject}" data-ages="${a.ages.join(' ')}" data-search="${e([a.title,a.description,a.tags,subjectLabel(a.subject),a.materials.join(' ')].join(' ').toLowerCase())}"><a href="${url(a)}"><div class="card-image"><img src="/assets/${a.art}.svg" alt="${e(a.alt)}" width="800" height="600" loading="lazy"><h3 class="image-title">${e(a.title)}</h3></div><div class="card-copy"><div class="card-meta"><span>Ages ${a.ageLabel}</span><span>${e(a.time)}</span></div><p>${e(a.description)}</p></div></a></article>`).join('')}</div>`;}
