const crumb=(parts)=>`<nav class="breadcrumbs wrap" aria-label="Breadcrumb"><a href="/">Home</a>${parts.map(([label,href])=>`<span aria-hidden="true">/</span>${href?`<a href="${href}">${e(label)}</a>`:`<span aria-current="page">${e(label)}</span>`}`).join('')}</nav>`;
