function catalogue(search=false){return crumb([[search?'Search':'All activities']])+heading(search?'SEARCH THE WHOLE SCHOOL':'THE ACTIVITY CUPBOARD',search?'What shall we discover?':'A little idea for today.',search?'Search every book, class, drawing lesson, flashcard set and activity — all free, no sign-up.':'Ten free activities. Everyday materials. Plenty of room to make them your own.')+`<section class="wrap section compact" data-catalogue>${alphabetShelf()}${drawingShelf()}<div class="bean-next"><h2>The Grow a Bean activity collection</h2>${beanLinks()}</div><div class="handwriting-cta"><div><h2>Write, trace & draw on screen.</h2><p>A space to practise letters, numbers and your name with a finger, stylus or mouse.</p></div><a class="button" href="/literacy/handwriting-practice/">Try handwriting ↗</a></div><form class="filters" role="search"><div class="search-field"><label for="query">${search?'Search the whole school':'Search activities'}</label><div>${svgSearch}<input id="query" name="q" type="search" placeholder="${search?'Try colors, books, drawing…':'Try plants, paper, patterns…'}" autocomplete="off"></div></div><div><label for="subject">Subject</label><select id="subject" name="subject"><option value="">All subjects</option>${subjects.map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select></div><div><label for="age">Age</label><select id="age" name="age"><option value="">All ages</option>${ageGroups.map(([slug,range])=>`<option value="${slug}">${range} years</option>`).join('')}</select></div><button class="clear-button" type="reset">Clear filters</button></form>${search?'<div class="sr" data-site-search hidden><p class="result-count" data-sr-count aria-live="polite" aria-atomic="true"></p><ul class="sr-list" data-sr-list></ul></div>':''}<noscript><p class="notice">Search needs JavaScript. All ten activities are listed below; you can also browse <a href="/subjects/">by subject</a> or <a href="/ages/">by age</a>.</p></noscript><p id="result-count" class="result-count" aria-live="polite" aria-atomic="true">10 activities to explore</p>${cards(activities)}<div id="no-results" class="empty-state" hidden><h2>No little adventures found.</h2><p>Try a broader word like “paper”, or clear a filter to see more ideas.</p><button class="button" type="button" data-clear>Show all activities</button></div></section>`;}
