page('/newborn/6-12-weeks/','Baby classes 6–12 weeks: Newborn 2','What to do with a baby at 6 to 12 weeks: high-contrast faces, patterns and gentle visual tracking games for calm, parent-led moments at home.',crumb([['Newborn','/newborn/'],['6–12 Weeks']])+heading('NEWBORN 2','6–12 weeks: faces, tracking and a first look at colour.','The second newborn class. Simple faces and patterns hold your baby’s attention a little longer, and slow side-to-side movement turns looking into early tracking.')+stagePageBody({chips:[['Age','6–12 Weeks'],['Class','Newborn 2'],['Subjects','Visual tracking, faces, sound']],stageLessons:[fvLesson],soon:`<div class="fc-stage lesson-soon"><div class="fc-stage-pills"><span class="fc-age">Next stage</span><span class="fc-class">3–4 Months</span></div><h3>Infant 1 is ready</h3><p>Colour and first objects are waiting at <a href="/baby/3-4-months/">3–4 months · Infant 1</a>.</p></div>`}));
page('/baby/3-4-months/','Baby classes 3–4 months: Infant 1','What to do with a baby at 3 to 4 months: bold red, yellow and blue cards and familiar first objects, in short parent-led visual sessions.',crumb([['Baby','/baby/'],['3–4 Months']])+heading('INFANT 1','3–4 months: colour, objects and reaching.','The Infant 1 class. Around this age many babies start to notice colour and reach toward what interests them, so this lesson pairs strong single colours with familiar objects.')+stagePageBody({chips:[['Age','3–4 Months'],['Class','Infant 1'],['Subjects','Vision, movement, communication']],stageLessons:[cfoLesson],soon:`<div class="fc-stage lesson-soon"><div class="fc-stage-pills"><span class="fc-age">Earlier stage</span><span class="fc-class">6–12 Weeks</span></div><h3>Start with Newborn 2</h3><p>Faces and visual tracking live at <a href="/newborn/6-12-weeks/">6–12 weeks · Newborn 2</a>.</p></div>`}));
