/* ---- Class 30 · Logic, Thinking & Problem-Solving: the class page, the game
   library and 30 real puzzle games including one fully traceable maze. ---- */
page(C30_PATH,'Class 30 · Logic, Thinking & Problem-Solving (Ages 4–5)','The Class 30 logic stage: 30 real picture-puzzle games with spoken instructions — patterns, odd ones out, shadow matching, size ordering, secret codes, clue logic and one traceable maze — plus a printable worksheet for every adventure.',logicClassBody(),{schema:[age4Bc(C30_PATH,[['Preschool','/preschool/'],['Age 4',HUB4],['Logic, Thinking & Problem-Solving',C30_PATH]])]});
page(LOGIC_LIB_PATH,'Logic Adventures — 30 picture puzzles with spoken instructions (ages 4–5)','Thirty real logic games built on our own puzzle artwork: finish patterns, catch odd ones, match shadows and sizes, follow keys and routes, trace a maze and crack secret codes — every prompt spoken aloud, no reading needed.',logicLibraryBody(),{schema:[age4Bc(LOGIC_LIB_PATH,[['Preschool','/preschool/'],['Logic Adventures',LOGIC_LIB_PATH]])]});
for(const g of logicAdventures){
 const p=LOGIC_LIB_PATH+g.slug+'/';
 page(p,`${g.title} — Logic Adventure for ages 4–5`,`${g.tag} A real, playable logic game from Kiddo.school’s Logic Adventures with spoken instructions, gentle hints and no scores.`,logicAdventureBody(g),{schema:[age4Bc(p,[['Preschool','/preschool/'],['Logic Adventures',LOGIC_LIB_PATH],[`${g.title}`,p]])]});
}

/* ---- The Worksheet Library: hub, five subject categories, every individual
   worksheet page and its real PDF. Worksheets stay their own resource type:
   separate URLs, separate schema, separate library. Downloading a worksheet
   never touches My Classroom progress. ---- */
page('/worksheets/','Free Printable Preschool Worksheets — the Kiddo.school Worksheet Library','Free printable worksheets for preschoolers: tracing guides, counting rows, coloring outlines, shape sorts and phonics sound games with parent scripts. Real PDF downloads, print-only buttons and a matching online game for every sheet.',worksheetsHubBody(),{schema:[hubBc(site)]});
for(const key of Object.keys(SUBJECTS)){
 const cat=WS_BASE+key+'/';
 const s=SUBJECTS[key];
 const n=subjectCounts[key];
 page(cat,`${s.label} Worksheets for Age 4 — Free Printables (Class ${s.classNum})`,`Free printable ${s.label.toLowerCase()} worksheets for 4-year-olds: ${n} activities with real PDF downloads, print-only buttons and the matching online game. Part of Class ${s.classNum} at Kiddo.school.`,worksheetCategoryBody(key),{schema:[categoryBc(site,key),CollectionSchema(site,key)]});
}
const wsImageCache=new Map();
function storyImage(w){
 const href=w.ws.imgHref;
 if(!wsImageCache.has(href)){
  const data=readFileSync('public'+href);
  const jpg=data; // JPEG bytes pass straight into the PDF (DCTDecode)
  wsImageCache.set(href,{data:jpg,w:Math.round(1400),h:Math.round(1400*(w.ws.ar))});
 }
 return wsImageCache.get(href);
}
for(const w of worksheets){
 const p=wsUrl(w.subject,w.slug);
 page(p,`${w.title} Worksheet — Free Printable for Age 4 (Class ${SUBJECTS[w.subject].classNum})`,w.metaDescription,worksheetPageBody(w),{schema:[worksheetBc(site,w),worksheetSchema(site,w)],ogImage:w.art.img,ogAlt:w.art.alt});
 const dl=pdfUrl(w.subject,w.slug);
 mkdirSync('dist'+dl.slice(0,dl.lastIndexOf('/')),{recursive:true});
 const story=w.wsType==='story';
 writeFileSync('dist'+dl,buildPDF({els:worksheetEls(w),W:595,H:842,title:w.title+' — Free Worksheet from Kiddo.school',subject:'Kiddo.school free printable worksheet (Class '+SUBJECTS[w.subject].classNum+')',images:story?[storyImage(w)]:undefined}));
}
/* Whole-school search index: written after the last page registers so it
   always covers the complete school — books, classes, drawing lessons,
   flashcards, activities and the pages parents need. */
writeFileSync('dist/assets/search-index.json',JSON.stringify(searchPages));
writeFileSync('dist/sitemap.xml',`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${allRoutes.map(p=>`<url><loc>${site+p}</loc></url>`).join('')}</urlset>\n`);
writeFileSync('dist/robots.txt',`User-agent: *\n${indexable?'Allow: /':'Disallow: /'}\nDisallow: /admin/\nDisallow: /api/\nSitemap: ${site}/sitemap.xml\n`);
writeFileSync('dist/_headers',`/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  X-Frame-Options: DENY\n  Permissions-Policy: camera=(), microphone=(), geolocation=()\n  Content-Security-Policy: default-src 'self'; script-src 'self' https://challenges.cloudflare.com; style-src 'self'; img-src 'self' https://pub-f2fcb7c9b45a496cbeefef18dbba0ec0.r2.dev; font-src 'self'; connect-src 'self' https://challenges.cloudflare.com; object-src 'none'; base-uri 'none'; frame-ancestors 'none'; frame-src https://challenges.cloudflare.com\n${indexable?'':'  X-Robots-Tag: noindex, follow\n'}`);
writeFileSync('dist/build-info.json',JSON.stringify({siteUrl:site,indexable,pages:allRoutes.length+2,activities:activities.length},null,2));
console.log(`Built ${allRoutes.length+2} pages and ${activities.length} activity sheets. Canonical origin: ${site}. Indexing: ${indexable?'enabled':'disabled (preview)'}.`);
